# Whitelist of allowed commands
ALLOWED_COMMANDS = {'ls', 'pwd', 'whoami', 'date', 'echo', 'cat', 'head', 'tail', 'wc'}

@app.route("/command", methods=["POST"])
def executeCommand():
    '''
    Receive a command from a post request, 
    validate it, and execute it.
    '''
    command = request.form.get('command') or request.json.get('command') if request.is_json else request.form.get('command')

    if not command:
        return {"error": "No command provided"}, 400

    # Parse the command to get the base command
    try:
        parsed_command = shlex.split(command)
    except ValueError as e:
        return {"error": f"Invalid command format: {str(e)}"}, 400

    if not parsed_command:
        return {"error": "Empty command"}, 400

    base_command = parsed_command[0]

    # Validate against whitelist
    if base_command not in ALLOWED_COMMANDS:
        return {"error": f"Command '{base_command}' is not allowed"}, 403

    # Check for dangerous characters/patterns
    dangerous_patterns = [';', '&&', '||', '|', '`', '$', '>', '<', '\n', '\r']
    for pattern in dangerous_patterns:
        if pattern in command:
            return {"error": "Invalid characters in command"}, 400

    try:
        # Execute the command safely
        result = subprocess.run(
            parsed_command,
            capture_output=True,
            text=True,
            timeout=30,
            shell=False
        )
        return {
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode
        }, 200
    except subprocess.TimeoutExpired:
        return {"error": "Command timed out"}, 408
    except FileNotFoundError:
        return {"error": f"Command '{base_command}' not found"}, 404
    except Exception as e:
        return {"error": f"Execution error: {str(e)}"}, 500

